    def get_response(self, text: str) -> Optional[str]:
        if not text:
            return None
        text_lower = text.lower()
        best = None
        best_len = -1
        for rule in self.rules:
            if rule['compiled'].search(text_lower):
                if len(rule['pattern']) > best_len:
                    best_len = len(rule['pattern'])
                    best = rule
        if best:
            return random.choice(best['responses'])
        return None